<?php
/**
 * Antalya POS Restaurant Table Delete Handler
 *
 * @package Antalya_POS
 * @since 6.4
 */

if (!defined('ABSPATH')) {
    exit;
}

if (isset($_GET['del_table'])) {
    if (!current_user_can('manage_options')) {
        wp_die(esc_html__('You do not have sufficient permissions to perform this action.', 'antalya-pos'));
    }

    $table_id = intval($_GET['del_table']);
    if ($table_id > 0) {
        // Verify CSRF nonce generated by wp_nonce_url() in table-list.php & table-view.php
        check_admin_referer('rtpos_delete_table_' . $table_id);

        global $wpdb;
        $t_tables  = $wpdb->prefix . 'rtpos_tables';
        $svg_check = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>';

        $deleted = $wpdb->delete(
            $t_tables,
            ['id' => $table_id],
            ['%d']
        );

        if ($deleted !== false) {
            echo '<div class="apos-alert" style="display:flex;align-items:center;gap:8px;">' . $svg_check . '<span>' . sprintf(
                /* translators: %d: table ID */
                esc_html__('Table #%d deleted successfully!', 'antalya-pos'),
                $table_id
            ) . '</span></div>';
        }
    }
}